window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-35ba3e0dbe6a8eaa"]={"versions": [{"id": "FIG-35ba3e0dbe6a8eaa", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungsbaum für Vorbedingungsprüfungen).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic / Adaptive Platform, BSW-Modul <code>E2EXf</code> (<em>E2E Transformer</em>, SWS-Kapitel 7 / Funktionsablauf).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der internen Verifikationsroutine <code>E2EXf_input_checks_PXXm()</code> zur Prüfung obligatorischer Schnittstellenparameter für Client-Server- bzw. nachrichtenbasierte E2E-Profile mit Metadaten-/Header-Extraktion (generisches Profilschema <code>PXXm</code>, wie z. B. P04m, P07m, P08m, P44m).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Parameter &amp; Datenobjekte:</strong>\n<ul class=\"fig-list\"><li><code>Profile</code>: Laufzeit- oder Konfigurationsparameter zur Identifikation des aktiven E2E-Profils.\n</li><li><code>PXXm</code>: Platzhalter-Klasse für E2E-Profile mit Metadaten-Unterstützung (SOME/IP-Header-Auswertung, Request/Response-Tracking).\n</li><li><code>extractProtocolHeaderFields</code> <em>(im Diagramm mit Spezifikationstypo als <code>extractPrtocolHeaderFields</code> dargestellt)</em>: Funktionszeiger (Callback) zur Extraktion von Protokollfeldern (z. B. Client-ID, Session-ID, Sequence-Counter aus dem oberen Protokoll-Header).\n</li><li><code>csTransactionHandle</code>: Zeiger/Handle auf den Client/Server-Transaktionskontext zur Korrelation von Aufruf und Rückmeldung.\n</li></ul>\n</li><li><strong>UML-Steuerelemente:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node).\n</li><li>Drei Entscheidungsknoten (Decision Diamonds) mit komplementären Guard-Bedingungen (<code>[TRUE]</code>, <code>[FALSE]</code>).\n</li><li>Zwei Aktivitätsendknoten (Activity Final Nodes) mit den booleschen Rückgabewerten <code>return [FALSE]</code> und <code>return [TRUE]</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner, blockierungsfreier Kontrollfluss vor Eintritt in die eigentliche E2E-Transformationslogik (<code>Protect</code> / <code>Check</code>):</p>\n<ol class=\"fig-list\"><li><strong>Profil-Klassifikation:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>Profile == PXXm</code>.\n</li><li><code>[FALSE]</code>-Zweig: Bei Nicht-PXXm-Profilen sind keine PXXm-spezifischen Zeiger erforderlich → unmittelbarer Übergang zu <code>return [TRUE]</code>.\n</li><li><code>[TRUE]</code>-Zweig: Einzugrenzen auf PXXm-Pfad → Weiterschaltung zu Schritt 2.\n</li></ul>\n</li><li><strong>Prüfung des Header-Extraktionszeigers:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>extractProtocolHeaderFields == NULL</code>.\n</li><li><code>[TRUE]</code>-Zweig: Ungültiger Funktionszeiger → Abbruch via <code>return [FALSE]</code>.\n</li><li><code>[FALSE]</code>-Zweig: Zeiger vorhanden → Weiterschaltung zu Schritt 3.\n</li></ul>\n</li><li><strong>Prüfung des Transaktions-Handles:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>csTransactionHandle == NULL</code>.\n</li><li><code>[TRUE]</code>-Zweig: Fehlendes Handle → Abbruch via <code>return [FALSE]</code>.\n</li><li><code>[FLASE]</code>-Zweig <em>(Spezifikationstypo für <code>[FALSE]</code>)</em>: Beide erforderlichen Parameter sind ungleich <code>NULL</code> → Abschluss via <code>return [TRUE]</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Fehlerbehandlung &amp; Safety-Vertrag (<code>SWS_E2EXf_00106</code>, <code>SWS_E2EXf_00180</code>):</strong>\n<ul class=\"fig-list\"><li>Liefert <code>E2EXf_input_checks_PXXm()</code> den Wert <code>FALSE</code> zurück, bricht der Transformer die Ausführung deterministisch mit dem Fehlercode <code>E_SAFETY_HARD_RUNTIMEERROR</code> ab. Es erfolgt keine Datenverarbeitung oder PDU-Weiterleitung.\n</li></ul>\n</li><li><strong>BSW- &amp; Treiber-Implementierung:</strong>\n<ul class=\"fig-list\"><li>Guard-Ausdrücke gegen Nullzeiger müssen zwingend vor jedem Speicher- oder Funktionszugriff ausgewertet werden, um Trap-/Kernel-Exceptions im BSW-Kontext zu verhindern.\n</li><li>Spezifikations-Hinweis: Die typografischen Fehler im Diagramm (<code>extractPrtocolHeaderFields</code> sowie Guard <code>[FLASE]</code>) sind in C-Implementierungen anhand der normativen Signatur aus <code>[SWS_E2EXf_00180]</code> (<code>extractProtocolHeaderFields</code> und <code>FALSE</code>) aufzulösen.\n</li></ul>\n</li><li><strong>RTE- &amp; Codegenerator-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Bei Konfiguration von Schnittstellen über Profile <code>P04m</code>, <code>P07m</code>, <code>P08m</code> oder <code>P44m</code> muss der BSW-/RTE-Generator sicherstellen, dass sowohl die Callback-Funktion zur Header-Extraktion als auch der Puffer für das Transaktions-Handle statisch instanziiert und dem Transformer übergeben werden.\n</li></ul>\n</li><li><strong>Anforderungs-Traceability:</strong> Dient der Umsetzung von <code>RS_E2E_08538</code> zur Absicherung nachrichtenbasierter und Client/Server-Kommunikationsmuster gegen Schnittstellen-Fehlkonfigurationen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f709196eb7ded3ac", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungsbaum für Vorbedingungsprüfungen).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic / Adaptive Platform, BSW-Modul <code>E2EXf</code> (<em>E2E Transformer</em>, SWS-Kapitel 7 / Funktionsablauf).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der internen Verifikationsroutine <code>E2EXf_input_checks_PXXm()</code> zur Prüfung obligatorischer Schnittstellenparameter für Client-Server- bzw. nachrichtenbasierte E2E-Profile mit Metadaten-/Header-Extraktion (generisches Profilschema <code>PXXm</code>, wie z. B. P04m, P07m, P08m, P44m).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Parameter &amp; Datenobjekte:</strong>\n<ul class=\"fig-list\"><li><code>Profile</code>: Laufzeit- oder Konfigurationsparameter zur Identifikation des aktiven E2E-Profils.\n</li><li><code>PXXm</code>: Platzhalter-Klasse für E2E-Profile mit Metadaten-Unterstützung (SOME/IP-Header-Auswertung, Request/Response-Tracking).\n</li><li><code>extractProtocolHeaderFields</code> <em>(im Diagramm mit Spezifikationstypo als <code>extractPrtocolHeaderFields</code> dargestellt)</em>: Funktionszeiger (Callback) zur Extraktion von Protokollfeldern (z. B. Client-ID, Session-ID, Sequence-Counter aus dem oberen Protokoll-Header).\n</li><li><code>csTransactionHandle</code>: Zeiger/Handle auf den Client/Server-Transaktionskontext zur Korrelation von Aufruf und Rückmeldung.\n</li></ul>\n</li><li><strong>UML-Steuerelemente:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node).\n</li><li>Drei Entscheidungsknoten (Decision Diamonds) mit komplementären Guard-Bedingungen (<code>[TRUE]</code>, <code>[FALSE]</code>), farblich codiert gemäß Legende für allgemeingültige Pfade (<em>All types</em>).\n</li><li>Zwei Aktivitätsendknoten (Activity Final Nodes) mit den booleschen Rückgabewerten <code>return [FALSE]</code> und <code>return [TRUE]</code>.\n</li></ul>\n</li><li><strong>Visuelle Zusatzelemente / Legende:</strong>\n<ul class=\"fig-list\"><li>Legendenkasten <em>Communication Types</em> zur Farbcodierung von Kommunikationsmustern: <em>All types</em> (Beige/Pfirsich), <em>Sender/Receiver</em> (Hellgrün), <em>Publisher/Subscriber</em> (Grün), <em>C/S: Server</em> (Hellblau), <em>C/S: Client</em> (Rosa), <em>Signal to Service</em> (Gelb).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner, blockierungsfreier Kontrollfluss vor Eintritt in die eigentliche E2E-Transformationslogik (<code>Protect</code> / <code>Check</code>):</p>\n<ol class=\"fig-list\"><li><strong>Profil-Klassifikation:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>Profile == PXXm</code>.\n</li><li><code>[FALSE]</code>-Zweig: Bei Nicht-PXXm-Profilen sind keine PXXm-spezifischen Zeiger erforderlich → unmittelbarer Übergang zu <code>return [TRUE]</code>.\n</li><li><code>[TRUE]</code>-Zweig: Einzugrenzen auf PXXm-Pfad → Weiterschaltung zu Schritt 2.\n</li></ul>\n</li><li><strong>Prüfung des Header-Extraktionszeigers:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>extractProtocolHeaderFields == NULL</code>.\n</li><li><code>[TRUE]</code>-Zweig: Ungültiger Funktionszeiger → Abbruch via <code>return [FALSE]</code>.\n</li><li><code>[FALSE]</code>-Zweig: Zeiger vorhanden → Weiterschaltung zu Schritt 3.\n</li></ul>\n</li><li><strong>Prüfung des Transaktions-Handles:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>csTransactionHandle == NULL</code>.\n</li><li><code>[TRUE]</code>-Zweig: Fehlendes Handle → Abbruch via <code>return [FALSE]</code>.\n</li><li><code>[FALSE]</code>-Zweig: Beide erforderlichen Parameter sind ungleich <code>NULL</code> → Abschluss via <code>return [TRUE]</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Fehlerbehandlung &amp; Safety-Vertrag (<code>SWS_E2EXf_00106</code>, <code>SWS_E2EXf_00180</code>):</strong>\n<ul class=\"fig-list\"><li>Liefert <code>E2EXf_input_checks_PXXm()</code> den Wert <code>FALSE</code> zurück, bricht der Transformer die Ausführung deterministisch mit dem Fehlercode <code>E_SAFETY_HARD_RUNTIMEERROR</code> ab. Es erfolgt keine Datenverarbeitung oder PDU-Weiterleitung.\n</li></ul>\n</li><li><strong>BSW- &amp; Treiber-Implementierung:</strong>\n<ul class=\"fig-list\"><li>Guard-Ausdrücke gegen Nullzeiger müssen zwingend vor jedem Speicher- oder Funktionszugriff ausgewertet werden, um Trap-/Kernel-Exceptions im BSW-Kontext zu verhindern.\n</li><li>Spezifikations-Hinweis: Die typografischen Fehler im Diagramm (<code>extractPrtocolHeaderFields</code> sowie Guard <code>[FLASE]</code>) sind in C-Implementierungen anhand der normativen Signatur aus <code>[SWS_E2EXf_00180]</code> (<code>extractProtocolHeaderFields</code> und <code>FALSE</code>) aufzulösen.\n</li></ul>\n</li><li><strong>RTE- &amp; Codegenerator-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Bei Konfiguration von Schnittstellen über Profile <code>P04m</code>, <code>P07m</code>, <code>P08m</code> oder <code>P44m</code> muss der BSW-/RTE-Generator sicherstellen, dass sowohl die Callback-Funktion zur Header-Extraktion als auch der Puffer für das Transaktions-Handle statisch instanziiert und dem Transformer übergeben werden.\n</li></ul>\n</li><li><strong>Anforderungs-Traceability:</strong> Dient der Umsetzung von <code>RS_E2E_08538</code> zur Absicherung nachrichtenbasierter und Client/Server-Kommunikationsmuster gegen Schnittstellen-Fehlkonfigurationen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-72d33dd2e56f39a3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungsbaum für Vorbedingungsprüfungen).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic / Adaptive Platform, BSW-Modul <code>E2EXf</code> (<em>E2E Transformer</em>, SWS-Kapitel 7 / Funktionsablauf).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der internen Verifikationsroutine <code>E2EXf_input_checks_PXXm()</code> zur Prüfung obligatorischer Schnittstellenparameter für Client-Server- bzw. nachrichtenbasierte E2E-Profile mit Metadaten-/Header-Extraktion (generisches Profilschema <code>PXXm</code>, wie z. B. P04m, P07m, P08m, P44m).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Parameter &amp; Datenobjekte:</strong>\n<ul class=\"fig-list\"><li><code>Profile</code>: Laufzeit- oder Konfigurationsparameter zur Identifikation des aktiven E2E-Profils.\n</li><li><code>PXXm</code>: Platzhalter-Klasse für E2E-Profile mit Metadaten-Unterstützung (SOME/IP-Header-Auswertung, Request/Response-Tracking).\n</li><li><code>extractProtocolHeaderFields</code> <em>(im Diagramm mit Spezifikationstypo als <code>extractPrtocolHeaderFields</code> dargestellt)</em>: Funktionszeiger (Callback) zur Extraktion von Protokollfeldern (z. B. Client-ID, Session-ID, Sequence-Counter aus dem oberen Protokoll-Header).\n</li><li><code>csTransactionHandle</code>: Zeiger/Handle auf den Client/Server-Transaktionskontext zur Korrelation von Aufruf und Rückmeldung.\n</li></ul>\n</li><li><strong>UML-Steuerelemente:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node).\n</li><li>Drei Entscheidungsknoten (Decision Diamonds) mit komplementären Guard-Bedingungen (<code>[TRUE]</code>, <code>[FALSE]</code>), farblich codiert gemäß Legende für allgemeingültige Pfade (<em>All types</em>).\n</li><li>Zwei Aktivitätsendknoten (Activity Final Nodes) mit den booleschen Rückgabewerten <code>return [FALSE]</code> und <code>return [TRUE]</code>.\n</li></ul>\n</li><li><strong>Visuelle Zusatzelemente / Legende:</strong>\n<ul class=\"fig-list\"><li>Legendenkasten <em>Legend</em> (zuvor <em>Communication Types</em>) zur Farbcodierung von Kommunikationsmustern: <em>All types</em> (Beige/Pfirsich), <em>Sender/Receiver</em> (Hellgrün), <em>Publisher/Subscriber</em> (Grün), <em>C/S: Server</em> (Hellblau), <em>C/S: Client</em> (Rosa), <em>Signal to Service</em> (Gelb).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner, blockierungsfreier Kontrollfluss vor Eintritt in die eigentliche E2E-Transformationslogik (<code>Protect</code> / <code>Check</code>):</p>\n<ol class=\"fig-list\"><li><strong>Profil-Klassifikation:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>Profile == PXXm</code>.\n</li><li><code>[FALSE]</code>-Zweig: Bei Nicht-PXXm-Profilen sind keine PXXm-spezifischen Zeiger erforderlich → unmittelbarer Übergang zu <code>return [TRUE]</code>.\n</li><li><code>[TRUE]</code>-Zweig: Einzugrenzen auf PXXm-Pfad → Weiterschaltung zu Schritt 2.\n</li></ul>\n</li><li><strong>Prüfung des Header-Extraktionszeigers:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>extractProtocolHeaderFields == NULL</code>.\n</li><li><code>[TRUE]</code>-Zweig: Ungültiger Funktionszeiger → Abbruch via <code>return [FALSE]</code>.\n</li><li><code>[FALSE]</code>-Zweig: Zeiger vorhanden → Weiterschaltung zu Schritt 3.\n</li></ul>\n</li><li><strong>Prüfung des Transaktions-Handles:</strong>\n<ul class=\"fig-list\"><li>Prüfung <code>csTransactionHandle == NULL</code>.\n</li><li><code>[TRUE]</code>-Zweig: Fehlendes Handle → Abbruch via <code>return [FALSE]</code>.\n</li><li><code>[FALSE]</code>-Zweig: Beide erforderlichen Parameter sind ungleich <code>NULL</code> → Abschluss via <code>return [TRUE]</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Fehlerbehandlung &amp; Safety-Vertrag (<code>SWS_E2EXf_00106</code>, <code>SWS_E2EXf_00180</code>):</strong>\n<ul class=\"fig-list\"><li>Liefert <code>E2EXf_input_checks_PXXm()</code> den Wert <code>FALSE</code> zurück, bricht der Transformer die Ausführung deterministisch mit dem Fehlercode <code>E_SAFETY_HARD_RUNTIMEERROR</code> ab. Es erfolgt keine Datenverarbeitung oder PDU-Weiterleitung.\n</li></ul>\n</li><li><strong>BSW- &amp; Treiber-Implementierung:</strong>\n<ul class=\"fig-list\"><li>Guard-Ausdrücke gegen Nullzeiger müssen zwingend vor jedem Speicher- oder Funktionszugriff ausgewertet werden, um Trap-/Kernel-Exceptions im BSW-Kontext zu verhindern.\n</li><li>Spezifikations-Hinweis: Die typografischen Fehler im Diagramm (<code>extractPrtocolHeaderFields</code> sowie Guard <code>[FLASE]</code>) sind in C-Implementierungen anhand der normativen Signatur aus <code>[SWS_E2EXf_00180]</code> (<code>extractProtocolHeaderFields</code> und <code>FALSE</code>) aufzulösen.\n</li></ul>\n</li><li><strong>RTE- &amp; Codegenerator-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Bei Konfiguration von Schnittstellen über Profile <code>P04m</code>, <code>P07m</code>, <code>P08m</code> oder <code>P44m</code> muss der BSW-/RTE-Generator sicherstellen, dass sowohl die Callback-Funktion zur Header-Extraktion als auch der Puffer für das Transaktions-Handle statisch instanziiert und dem Transformer übergeben werden.\n</li></ul>\n</li><li><strong>Anforderungs-Traceability:</strong> Dient der Umsetzung von <code>RS_E2E_08538</code> zur Absicherung nachrichtenbasierter und Client/Server-Kommunikationsmuster gegen Schnittstellen-Fehlkonfigurationen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-35ba3e0dbe6a8eaa", "to": "FIG-f709196eb7ded3ac", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Hinzufügen eines Legendenkastens („Communication Types“) mit Farbkennzeichnungen für Kommunikationsmuster (Entscheidungsknoten im Diagramm sind der Kategorie „All types“ zugeordnet).\n</li><li>Korrektur des Tippfehlers in der Guard-Bedingung am dritten Entscheidungsknoten (<code>csTransactionHandle == NULL</code>) von <code>[FLASE]</code> zu <code>[FALSE]</code>.\n</li><li>Bereinigung des Layouts und der Platzierung der Rückgabewerte an den beiden Aktivitätsendknoten (<code>return</code> mit Guard-Ergebnis <code>[FALSE]</code> bzw. <code>[TRUE]</code>).\n</li></ul>"}, {"from": "FIG-f709196eb7ded3ac", "to": "FIG-72d33dd2e56f39a3", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umbenennung des Titels des Legendenkastens von „Communication Types“ zu „Legend“.\n</li></ul>"}]};
